import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"SQLite Index & Performance","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md","lastUpdated":1786221059000}'),d={name:"reference/index.md"};function o(l,e,i,r,c,g){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="sqlite-index-performance" tabindex="-1">SQLite Index &amp; Performance <a class="header-anchor" href="#sqlite-index-performance" aria-label="Permalink to &quot;SQLite Index &amp; Performance&quot;">​</a></h1><p>Chanakya MCP compiles the structural AST of your repository into an embedded SQLite database at <code>&lt;project&gt;/.chanakya/index.db</code>.</p><div class="custom-banner"><div class="custom-banner-icon">âš¡</div><div class="custom-banner-content"><h4>Sub-Millisecond Relational Storage</h4><p>All tables are indexed on primary lookup paths: symbol names, file paths, parent IDs, and relational graph edge targets.</p></div></div><hr><h2 id="relational-database-schema" tabindex="-1">Relational Database Schema <a class="header-anchor" href="#relational-database-schema" aria-label="Permalink to &quot;Relational Database Schema&quot;">​</a></h2><p>The index is organized into eight optimized relational tables:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Table</th><th style="text-align:left;">Columns</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>files</code></strong></td><td style="text-align:left;"><code>path</code>, <code>language</code>, <code>size</code>, <code>mtime</code>, <code>hash</code>, <code>package</code></td><td style="text-align:left;">Primary file registry and change-detection baseline.</td></tr><tr><td style="text-align:left;"><strong><code>symbols</code></strong></td><td style="text-align:left;"><code>id</code>, <code>file_path</code>, <code>name</code>, <code>kind</code>, <code>start_line</code>, <code>end_line</code>, <code>signature</code>, <code>export_kind</code></td><td style="text-align:left;">Core symbol declarations and location bounds.</td></tr><tr><td style="text-align:left;"><strong><code>relationships</code></strong></td><td style="text-align:left;"><code>source_id</code>, <code>target_id</code>, <code>target_name</code>, <code>kind</code>, <code>confidence</code></td><td style="text-align:left;">Graph edges (<code>contains</code>, <code>calls</code>, <code>extends</code>, etc.).</td></tr><tr><td style="text-align:left;"><strong><code>references</code></strong></td><td style="text-align:left;"><code>name_id</code>, <code>file_path</code>, <code>start_line</code>, <code>start_col</code>, <code>enclosing_symbol_id</code></td><td style="text-align:left;">Every semantic identifier occurrence.</td></tr><tr><td style="text-align:left;"><strong><code>reference_names</code></strong></td><td style="text-align:left;"><code>id</code>, <code>name</code></td><td style="text-align:left;">Interned dictionary mapping 2M+ reference strings to integers.</td></tr><tr><td style="text-align:left;"><strong><code>imports</code></strong></td><td style="text-align:left;"><code>file_path</code>, <code>specifier</code>, <code>imported_name</code>, <code>local_name</code>, <code>resolved_path</code></td><td style="text-align:left;">Static module import bindings.</td></tr><tr><td style="text-align:left;"><strong><code>exports</code></strong></td><td style="text-align:left;"><code>file_path</code>, <code>name</code>, <code>local_name</code>, <code>source_path</code>, <code>is_reexport</code></td><td style="text-align:left;">Exported module members and barrel bindings.</td></tr><tr><td style="text-align:left;"><strong><code>metadata</code></strong></td><td style="text-align:left;"><code>schema_version</code>, <code>indexed_at</code>, <code>total_files</code>, <code>total_symbols</code></td><td style="text-align:left;">Database version and runtime stats.</td></tr></tbody></table><hr><h2 id="reference-string-interning-schema-v4" tabindex="-1">Reference String Interning (Schema v4) <a class="header-anchor" href="#reference-string-interning-schema-v4" aria-label="Permalink to &quot;Reference String Interning (Schema v4)&quot;">​</a></h2><p>On large repositories (e.g. 5,000+ files), storing raw strings for millions of identifier references causes database bloat.</p><p>Codebrain implements <strong>reference interning</strong>:</p><ul><li>2,000,000+ raw references collapse into ~55,000 distinct dictionary entries in <code>reference_names</code>.</li><li>Reduces index disk footprint by over <strong>75%</strong>, keeping memory cache hot and query times fast.</li></ul><hr><h2 id="_2-stage-incremental-indexing" tabindex="-1">2-Stage Incremental Indexing <a class="header-anchor" href="#_2-stage-incremental-indexing" aria-label="Permalink to &quot;2-Stage Incremental Indexing&quot;">​</a></h2><p>Reindexing never re-parses unchanged files:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>File Modified Event</span></span>
<span class="line"><span>       â†“</span></span>
<span class="line"><span>Stage 1: Size &amp; Mtime Check (18ms stat scan)</span></span>
<span class="line"><span>       â†“ (If mismatch)</span></span>
<span class="line"><span>Stage 2: Content SHA-256 Hash Verification</span></span>
<span class="line"><span>       â†“ (If hash changed)</span></span>
<span class="line"><span>Cascade-delete old file rows &amp; Reinsert in single transaction</span></span></code></pre></div><h3 id="racily-clean-timestamp-protection" tabindex="-1">Racily-Clean Timestamp Protection <a class="header-anchor" href="#racily-clean-timestamp-protection" aria-label="Permalink to &quot;Racily-Clean Timestamp Protection&quot;">​</a></h3><p>Filesystems have coarse timestamp resolution (1s on ext4, 2s on FAT). If a file is edited within two seconds of being indexed with identical byte count, Codebrain does not trust the mtime aloneâ€”it evaluates the content hash to guarantee zero stale data.</p><hr><h2 id="performance-measurements" tabindex="-1">Performance Measurements <a class="header-anchor" href="#performance-measurements" aria-label="Permalink to &quot;Performance Measurements&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">Codebrain Codebase (103 files)</th><th style="text-align:left;">Stress Monorepo (5,123 files)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Full Initial Index</strong></td><td style="text-align:left;"><strong>1.6 seconds</strong></td><td style="text-align:left;">~230 seconds</td></tr><tr><td style="text-align:left;"><strong>Incremental Reindex</strong></td><td style="text-align:left;"><strong>18 - 24 ms</strong></td><td style="text-align:left;"><strong>45 - 80 ms</strong></td></tr><tr><td style="text-align:left;"><strong>Symbol Lookup Latency</strong></td><td style="text-align:left;"><strong>~0.05 ms</strong></td><td style="text-align:left;"><strong>~0.08 ms</strong></td></tr><tr><td style="text-align:left;"><strong>Database Size on Disk</strong></td><td style="text-align:left;"><strong>2.0 MB</strong></td><td style="text-align:left;">256 MB (interned)</td></tr><tr><td style="text-align:left;"><strong>Extracted Symbols</strong></td><td style="text-align:left;">655 symbols</td><td style="text-align:left;">122,936 symbols</td></tr><tr><td style="text-align:left;"><strong>Relational Edges</strong></td><td style="text-align:left;">1,840 edges</td><td style="text-align:left;">370,534 relationships</td></tr></tbody></table>`,21)])])}const f=t(d,[["render",o]]);export{p as __pageData,f as default};
